-- ============================================================================
-- PLATFORM DETECTION
-- ============================================================================

local platform = (FuPLATFORM_WINDOWS and "Windows")
              or (FuPLATFORM_MAC and "Mac")
              or (FuPLATFORM_LINUX and "Linux")
              or "Unknown"

local pathSep = (platform == "Windows") and "\\" or "/"

-- Dialog window flags: macOS needs a Tool window (plus the
-- WA_MacAlwaysShowToolWindow attribute after AddWindow) to keep the frameless
-- dialog floating above Resolve's main window - without it the dialog can
-- open hidden behind Resolve with no title bar or dock entry to find it.
-- On Windows/Linux Tool windows get no taskbar entry and a non-standard
-- frame, so use a regular window there instead.
-- NOTE: the installer dialog is intentionally FRAMELESS, so these flags match
-- the frameless-probe flags in UI.getAutoCenterPoint() (src/lib/modules/ui.lua),
-- NOT UI.getDialogFlags() (which builds normal framed windows). The installer
-- cannot require ResolveKit - keep in sync with the probe flags there.
local function dialogWindowFlags()
    if platform == "Mac" then
        return { FramelessWindowHint = true, Tool = true }
    end
    return { FramelessWindowHint = true, Window = true }
end

local function applyDialogPlatformAttributes(win)
    if platform == "Mac" then
        win:SetAttribute('WA_MacAlwaysShowToolWindow', true)
    end
end

-- ============================================================================
-- RESOLVE THEME DETECTION
-- ============================================================================

-- Detect Resolve's UI theme by reading config.user.xml. Returns "gray" or
-- "blue". true = gray/classic; false or key absent in a readable file = blue;
-- file missing/unreadable = "gray" (safe fallback).
-- NOTE: deliberate dependency-free copy of Core.getResolveTheme() in
-- src/lib/modules/core.lua (the installer cannot require ResolveKit) - keep
-- both in sync.
local function detectResolveTheme()
    local path
    if platform == "Mac" then
        local home = os.getenv("HOME")
        path = home and (home .. "/Library/Preferences/Blackmagic Design/DaVinci Resolve/config.user.xml")
    elseif platform == "Windows" then
        local appData = os.getenv("APPDATA")  -- documented Resolve preferences location (best-effort)
        path = appData and (appData .. "\\Blackmagic Design\\DaVinci Resolve\\Preferences\\config.user.xml")
    else
        local home = os.getenv("HOME")        -- documented Resolve preferences location (best-effort)
        path = home and (home .. "/.local/share/DaVinciResolve/configs/config.user.xml")
    end
    if not path then return "gray" end

    local f = io.open(path, "r")
    if not f then return "gray" end
    local content = f:read("*all")
    f:close()
    if not content then return "gray" end

    local v = content:match("<IsGrayUserInterfaceEnabled>%s*(%a+)%s*</IsGrayUserInterfaceEnabled>")
    return (v == "true") and "gray" or "blue"
end

