-- ============================================================================
-- HELPER FUNCTIONS
-- ============================================================================

local function consolePrint(msg)
    local cmp = fusion.CurrentComp
    if cmp then
        cmp:Print(tostring(msg) .. "\n")
    else
        print(tostring(msg))
    end
end

local function getInstallPath()
    -- Primary: Use Fusion PathMap
    local scriptsPath = app:MapPath("Scripts:/Utility/")
    if scriptsPath and scriptsPath ~= "" and scriptsPath ~= "Scripts:/Utility/" then
        return scriptsPath .. "EditorScripts" .. pathSep
    end

    -- Fallback: Known platform-specific paths
    if platform == "Mac" then
        return "/Library/Application Support/Blackmagic Design/DaVinci Resolve/Fusion/Scripts/Utility/EditorScripts/"
    elseif platform == "Windows" then
        -- Per-user path under Support\Fusion is where Resolve maps Scripts:/
        -- on Windows (verified on Windows installs); ProgramData is secondary.
        local appdata = os.getenv("APPDATA")
        if appdata then
            return appdata .. "\\Blackmagic Design\\DaVinci Resolve\\Support\\Fusion\\Scripts\\Utility\\EditorScripts\\"
        end
        local programdata = os.getenv("PROGRAMDATA")
        if programdata then
            return programdata .. "\\Blackmagic Design\\DaVinci Resolve\\Fusion\\Scripts\\Utility\\EditorScripts\\"
        end
    elseif platform == "Linux" then
        return "/var/BlackmagicDesign/DaVinci Resolve/Fusion/Scripts/Utility/EditorScripts/"
    end

    return nil
end

-- ============================================================================
-- INSTALL LOGIC
-- ============================================================================

-- True if version a is strictly newer than b ("0.2.0" > "0.1.9"; "0.2" == "0.2.0")
local function isNewerVersion(a, b)
    local function segments(v)
        local t = {}
        for n in tostring(v):gmatch("%d+") do
            t[#t + 1] = tonumber(n)
        end
        return t
    end
    local sa, sb = segments(a), segments(b)
    for i = 1, math.max(#sa, #sb) do
        local x, y = sa[i] or 0, sb[i] or 0
        if x ~= y then
            return x > y
        end
    end
    return false
end

-- Reads the VERSION literal from an installed script/tool file (survives
-- minification). Returns nil if the file is missing or has no parsable version.
local function getInstalledVersion(path)
    local f = io.open(path, "r")
    if not f then
        return nil
    end
    local content = f:read("*all")
    f:close()
    return content and content:match('VERSION%s*=%s*"([^"]+)"') or nil
end

-- Installs/updates the bundled utility tools into Tools/. Skips tools whose
-- installed version is already >= the embedded one (never downgrades).
local function installTools(installPath)
    local toolsDir = installPath .. "Tools" .. pathSep
    bmd.createdir(toolsDir)

    for _, tool in ipairs(TOOLS) do
        local destFile = toolsDir .. tool.filename
        local installedVersion = getInstalledVersion(destFile)

        if installedVersion and not isNewerVersion(tool.version, installedVersion) then
            consolePrint("[EditorScripts Installer] Tool up to date, skipped: "
                .. tool.name .. " (installed v" .. installedVersion .. ")")
        else
            local file, writeErr = io.open(destFile, "w")
            if not file then
                consolePrint("[EditorScripts Installer] WARNING: Could not install tool "
                    .. tool.name .. ": " .. tostring(writeErr))
            else
                file:write(tool.content)
                file:close()
                if installedVersion then
                    consolePrint("[EditorScripts Installer] Updated tool: " .. tool.name
                        .. " v" .. installedVersion .. " -> v" .. tool.version)
                else
                    consolePrint("[EditorScripts Installer] Installed tool: "
                        .. tool.name .. " v" .. tool.version)
                end
            end
        end
    end
end

-- Writes one embedded script entry into installPath and verifies it landed.
local function writeScriptFile(installPath, entry)
    local destFile = installPath .. entry.filename

    local file, writeErr = io.open(destFile, "w")
    if not file then
        consolePrint("[EditorScripts Installer] ERROR: Could not write to: " .. destFile)
        return false, "Could not write to the scripts folder.\nError: " .. (writeErr or "unknown")
    end

    file:write(entry.content)
    file:close()

    -- Verify the file was written
    local verify = io.open(destFile, "r")
    if not verify then
        consolePrint("[EditorScripts Installer] ERROR: File could not be verified after writing.")
        return false, "File could not be verified after writing.\nCheck permissions and try again."
    end
    verify:close()

    return true, nil
end

-- Installs the given script entries, then the bundled utility tools.
-- opts.skipUpToDate = true skips entries whose installed version is already
-- >= the embedded one (never downgrades); false always overwrites (classic
-- single-script behavior). opts.announceEach = true prints one console line
-- per installed/updated entry (suite mode; the single-script flow prints its
-- own summary instead). Returns a results list ({entry, status =
-- "installed"|"updated"|"skipped"|"failed", installedVersion, err}), plus
-- allOk and the first error message.
local function installScripts(installPath, entries, opts)
    opts = opts or {}
    bmd.createdir(installPath)

    local results = {}
    local allOk = true
    local firstErr = nil

    for _, entry in ipairs(entries) do
        local destFile = installPath .. entry.filename
        local installedVersion = getInstalledVersion(destFile)

        if opts.skipUpToDate and installedVersion
            and not isNewerVersion(entry.version, installedVersion) then
            consolePrint("[EditorScripts Installer] Up to date, skipped: "
                .. entry.name .. " (installed v" .. installedVersion .. ")")
            results[#results + 1] = { entry = entry, status = "skipped", installedVersion = installedVersion }
        else
            if not opts.skipUpToDate then
                local existing = io.open(destFile, "r")
                if existing then
                    existing:close()
                    consolePrint("[EditorScripts Installer] Overwriting existing file: " .. destFile)
                end
            end

            local ok, err = writeScriptFile(installPath, entry)
            if ok then
                if installedVersion then
                    if opts.announceEach then
                        consolePrint("[EditorScripts Installer] Updated: " .. entry.name
                            .. " v" .. installedVersion .. " -> v" .. entry.version)
                    end
                    results[#results + 1] = { entry = entry, status = "updated", installedVersion = installedVersion }
                else
                    if opts.announceEach then
                        consolePrint("[EditorScripts Installer] Installed: "
                            .. entry.name .. " v" .. entry.version)
                    end
                    results[#results + 1] = { entry = entry, status = "installed" }
                end
            else
                allOk = false
                firstErr = firstErr or err
                results[#results + 1] = { entry = entry, status = "failed", err = err }
            end
        end
    end

    -- Install bundled utility tools; failure here must never fail the main install
    local toolsOk, toolsErr = pcall(installTools, installPath)
    if not toolsOk then
        consolePrint("[EditorScripts Installer] WARNING: Utility tools install failed: " .. tostring(toolsErr))
    end

    return results, allOk, firstErr
end

-- Classic single-script install: always overwrites, reports one result.
local function performInstall(installPath)
    local entry = SCRIPTS[1]
    local _, allOk, firstErr = installScripts(installPath, SCRIPTS, { skipUpToDate = false })
    if not allOk then
        return false, firstErr
    end

    consolePrint("[EditorScripts Installer] Successfully installed: " .. entry.name .. " v" .. entry.version)
    consolePrint("[EditorScripts Installer] Location: " .. installPath .. entry.filename)

    return true, nil
end

