local function showInstallerDialog()
    local ui = app.UIManager
    local disp = bmd.UIDispatcher(ui)

    local script = SCRIPTS[1]
    local installPath = getInstallPath()
    local winID = "ESInstallerWin"
    local DIALOG_PADDING = 28
    local DIALOG_WIDTH = 320
    local DIALOG_HEIGHT = 360
    local CONTENT_WIDTH = DIALOG_WIDTH - (DIALOG_PADDING * 2)
    local ICON_SIZE = {CONTENT_WIDTH, 70}

    local win = disp:AddWindow({
        ID = winID,
        TargetID = winID,
        WindowTitle = "EditorScripts Installer",
        StyleSheet = "* { background-color: " .. COLORS.bg .. "; color: " .. COLORS.primary .. "; }",
        WindowFlags = dialogWindowFlags(),
        Events = {
            Close = true,
        },
    }, ui:VGroup{
        ID = "DialogRoot",
        MinimumSize = {DIALOG_WIDTH, DIALOG_HEIGHT},
        MaximumSize = {DIALOG_WIDTH, DIALOG_HEIGHT},
        Spacing = 0,

        -- Horizontal padding wrapper
        ui:HGroup{
            Spacing = 0,
            Weight = 1,
            ui:HGap(28),

            ui:VGroup{
                Weight = 1,
                Spacing = 0,

                -- ==============================================================
                -- DEFAULT STATE
                -- ==============================================================
                ui:VGroup{
                    ID = "DefaultView",
                    Weight = 1,
                    Spacing = 0,

                    ui:VGap(28),

                    -- Logo icon
                    ui:Label{
                        ID = "DefaultIcon",
                        Text = logoIcon(),
                        MinimumSize = ICON_SIZE,
                        MaximumSize = ICON_SIZE,
                        Weight = 0,
                        StyleSheet = ICON_STYLE,
                    },

                    ui:VGap(24),

                    -- Script name
                    ui:Label{
                        ID = "ScriptNameLabel",
                        Text = script.name,
                        Alignment = { AlignHCenter = true },
                        Font = ui:Font{ PixelSize = 20 },
                        Weight = 0,
                        StyleSheet = "font-weight: 600; color: " .. COLORS.primary .. ";",
                    },

                    ui:VGap(10),

                    -- Version pill badge
                    ui:HGroup{
                        Weight = 0,
                        ui:HGap(0, 1),
                        ui:Label{
                            ID = "VersionBadge",
                            Text = "v" .. script.version,
                            Weight = 0,
                            StyleSheet = VERSION_BADGE_STYLE,
                        },
                        ui:HGap(0, 1),
                    },

                    ui:VGap(0, 1),

                    -- Install button
                    ui:HGroup{
                        Weight = 0,
                        Spacing = 0,
                        ui:Button{
                            ID = "InstallButton",
                            Text = "Install",
                            Weight = 1,
                            MinimumSize = {0, 44},
                            StyleSheet = PRIMARY_BUTTON_STYLE,
                        },
                    },

                    ui:VGap(10),

                    -- Cancel button
                    ui:HGroup{
                        Weight = 0,
                        Spacing = 0,
                        ui:Button{
                            ID = "CancelButton",
                            Text = "Cancel",
                            Weight = 1,
                            MinimumSize = {0, 44},
                            StyleSheet = SECONDARY_BUTTON_STYLE,
                        },
                    },

                    ui:VGap(28),
                },

                -- ==============================================================
                -- SUCCESS STATE
                -- ==============================================================
                ui:VGroup{
                    ID = "SuccessView",
                    Hidden = true,
                    Weight = 1,
                    Spacing = 0,

                    ui:VGap(28),

                    -- Success icon
                    ui:Label{
                        ID = "SuccessIcon",
                        Text = successIcon(),
                        MinimumSize = ICON_SIZE,
                        MaximumSize = ICON_SIZE,
                        Weight = 0,
                        StyleSheet = ICON_STYLE,
                    },

                    ui:VGap(24),

                    -- Title
                    ui:Label{
                        Text = "Installation Complete",
                        Alignment = { AlignHCenter = true },
                        Font = ui:Font{ PixelSize = 20 },
                        Weight = 0,
                        StyleSheet = "font-weight: 600; color: " .. COLORS.primary .. ";",
                    },

                    ui:VGap(12),

                    -- Message
                    ui:Label{
                        ID = "SuccessMessage",
                        Text = script.name .. " is ready to use.\nFind it in Workspace → Scripts → EditorScripts.",
                        Alignment = { AlignHCenter = true },
                        Font = ui:Font{ PixelSize = 12 },
                        Weight = 0,
                        WordWrap = true,
                        StyleSheet = "color: " .. COLORS.secondary .. ";",
                    },

                    ui:VGap(0, 1),

                    -- Close button
                    ui:HGroup{
                        Weight = 0,
                        Spacing = 0,
                        ui:Button{
                            ID = "CloseButton",
                            Text = "Close",
                            Weight = 1,
                            MinimumSize = {0, 44},
                            StyleSheet = PRIMARY_BUTTON_STYLE,
                        },
                    },

                    ui:VGap(10),

                    -- Open Install Folder button
                    ui:HGroup{
                        Weight = 0,
                        Spacing = 0,
                        ui:Button{
                            ID = "OpenFolderButton",
                            Text = "Open Install Folder",
                            Weight = 1,
                            MinimumSize = {0, 44},
                            StyleSheet = SECONDARY_BUTTON_STYLE,
                        },
                    },

                    ui:VGap(28),
                },

                -- ==============================================================
                -- FAILURE STATE
                -- ==============================================================
                ui:VGroup{
                    ID = "FailureView",
                    Hidden = true,
                    Weight = 1,
                    Spacing = 0,

                    ui:VGap(28),

                    -- Failure icon
                    ui:Label{
                        ID = "FailureIcon",
                        Text = failureIcon(),
                        MinimumSize = ICON_SIZE,
                        MaximumSize = ICON_SIZE,
                        Weight = 0,
                        StyleSheet = ICON_STYLE,
                    },

                    ui:VGap(24),

                    -- Title
                    ui:Label{
                        Text = "Installation Failed",
                        Alignment = { AlignHCenter = true },
                        Font = ui:Font{ PixelSize = 20 },
                        Weight = 0,
                        StyleSheet = "font-weight: 600; color: " .. COLORS.primary .. ";",
                    },

                    ui:VGap(12),

                    -- Message
                    ui:Label{
                        ID = "FailureMessage",
                        Text = "Could not write to the scripts folder.\nCheck permissions and try again.",
                        Alignment = { AlignHCenter = true },
                        Font = ui:Font{ PixelSize = 12 },
                        Weight = 0,
                        WordWrap = true,
                        StyleSheet = "color: " .. COLORS.secondary .. ";",
                    },

                    ui:VGap(0, 1),

                    -- Try Again button
                    ui:HGroup{
                        Weight = 0,
                        Spacing = 0,
                        ui:Button{
                            ID = "RetryButton",
                            Text = "Try Again",
                            Weight = 1,
                            MinimumSize = {0, 44},
                            StyleSheet = PRIMARY_BUTTON_STYLE,
                        },
                    },

                    ui:VGap(10),

                    -- Cancel button
                    ui:HGroup{
                        Weight = 0,
                        Spacing = 0,
                        ui:Button{
                            ID = "FailCancelButton",
                            Text = "Cancel",
                            Weight = 1,
                            MinimumSize = {0, 44},
                            StyleSheet = SECONDARY_BUTTON_STYLE,
                        },
                    },

                    ui:VGap(28),
                },
            },

            ui:HGap(28),
        },
    })

    local itm = win:GetItems()

    -- ========================================================================
    -- STATE MANAGEMENT
    -- ========================================================================

    local function switchState(state)
        itm.DefaultView.Hidden  = (state ~= "default")
        itm.SuccessView.Hidden  = (state ~= "success")
        itm.FailureView.Hidden  = (state ~= "failure")
        win:RecalcLayout()
    end

    -- ========================================================================
    -- EVENT HANDLERS
    -- ========================================================================

    function win.On.ESInstallerWin.Close(ev)
        disp:ExitLoop()
    end

    function win.On.CancelButton.Clicked(ev)
        disp:ExitLoop()
    end

    function win.On.OpenFolderButton.Clicked(ev)
        bmd.openfileexternal("Open", installPath)
        disp:ExitLoop()
    end

    function win.On.CloseButton.Clicked(ev)
        disp:ExitLoop()
    end

    function win.On.FailCancelButton.Clicked(ev)
        disp:ExitLoop()
    end

    function win.On.InstallButton.Clicked(ev)
        if not installPath then
            itm.FailureMessage.Text = "Could not detect the Fusion Scripts folder.\nCopy the script into Fusion/Scripts/Utility manually."
            switchState("failure")
            return
        end

        local success, errMsg = performInstall(installPath)
        if success then
            switchState("success")
        else
            itm.FailureMessage.Text = errMsg or "Could not write to the scripts folder.\nCheck permissions and try again."
            switchState("failure")
        end
    end

    function win.On.RetryButton.Clicked(ev)
        if not installPath then
            return
        end

        local success, errMsg = performInstall(installPath)
        if success then
            switchState("success")
        else
            itm.FailureMessage.Text = errMsg or "Could not write to the scripts folder.\nCheck permissions and try again."
        end
    end

    -- Ctrl+W / Ctrl+F4 hotkey to close window
    app:AddConfig(winID, {
        Target {
            ID = winID,
        },
        Hotkeys {
            Target = winID,
            Defaults = true,
            CONTROL_W = "Execute{ cmd = [[ app.UIManager:QueueEvent(obj, 'Close', {}) ]] }",
            CONTROL_F4 = "Execute{ cmd = [[ app.UIManager:QueueEvent(obj, 'Close', {}) ]] }",
        },
    })

    -- Show window
    applyDialogPlatformAttributes(win)
    win:Resize({DIALOG_WIDTH, DIALOG_HEIGHT})
    win:RecalcLayout()
    win:Show()
    disp:RunLoop()
    win:Hide()
    app:RemoveConfig(winID)
    collectgarbage()
end

-- ============================================================================
-- SUITE INSTALLER DIALOG
-- ============================================================================

-- Shown when the installer bundles more than one script. Opens with the same
-- compact Install/Cancel window as the single-script installer plus a Custom
-- Installation button; pressing it closes the compact window and pops up a
-- larger per-script selection window (each window auto-centers for its own
-- size). Both install paths skip scripts that are already up to date (never
-- downgrade). Results from either path show in the larger window.
local function showSuiteDialog()
    local ui = app.UIManager
    local disp = bmd.UIDispatcher(ui)

    local installPath = getInstallPath()

    -- Per-script install status, computed once and shared by both windows
    local statuses = {}
    for i, entry in ipairs(SCRIPTS) do
        local installed = installPath and getInstalledVersion(installPath .. entry.filename) or nil
        if not installPath then
            statuses[i] = { text = "Install path unknown", checked = true }
        elseif not installed then
            statuses[i] = { text = "Not installed", checked = true }
        elseif isNewerVersion(entry.version, installed) then
            statuses[i] = { text = "Update available: v" .. installed .. " → v" .. entry.version, checked = true }
        else
            statuses[i] = { text = "Up to date (v" .. installed .. ")", checked = false }
        end
    end

    -- Installs the selected entries (selected: index -> true). Returns one
    -- result line per SCRIPTS index plus overall success; up-to-date scripts
    -- are skipped (never downgraded).
    local function runInstall(selected)
        local entries = {}
        for i, entry in ipairs(SCRIPTS) do
            if selected[i] then
                entries[#entries + 1] = entry
            end
        end

        local results, allOk = installScripts(installPath, entries,
            { skipUpToDate = true, announceEach = true })

        local byEntry = {}
        for _, r in ipairs(results) do
            byEntry[r.entry] = r
        end

        local lines = {}
        for i, entry in ipairs(SCRIPTS) do
            local r = byEntry[entry]
            if not r then
                lines[i] = "Not selected"
            elseif r.status == "installed" then
                lines[i] = "Installed v" .. entry.version
            elseif r.status == "updated" then
                lines[i] = "Updated v" .. r.installedVersion .. " → v" .. entry.version
            elseif r.status == "skipped" then
                lines[i] = "Up to date, skipped (v" .. r.installedVersion .. ")"
            else
                lines[i] = "Install failed"
            end
        end

        return lines, allOk
    end

    -- ========================================================================
    -- MAIN WINDOW (individual-installer layout plus one extra button)
    -- ========================================================================

    -- Returns "install", "custom", or nil (cancelled/closed).
    local function showMainWindow()
        local winID = "ESSuiteInstallerWin"
        local DIALOG_PADDING = 28
        local DIALOG_WIDTH = 320
        -- Individual installer height (360) + one extra button row (44 + 10)
        local DIALOG_HEIGHT = 414
        local CONTENT_WIDTH = DIALOG_WIDTH - (DIALOG_PADDING * 2)
        local ICON_SIZE = {CONTENT_WIDTH, 70}
        local action = nil

        local win = disp:AddWindow({
            ID = winID,
            TargetID = winID,
            WindowTitle = "EditorScripts Installer",
            StyleSheet = "* { background-color: " .. COLORS.bg .. "; color: " .. COLORS.primary .. "; }",
            WindowFlags = dialogWindowFlags(),
            Events = {
                Close = true,
            },
        }, ui:VGroup{
            ID = "DialogRoot",
            MinimumSize = {DIALOG_WIDTH, DIALOG_HEIGHT},
            MaximumSize = {DIALOG_WIDTH, DIALOG_HEIGHT},
            Spacing = 0,

            -- Horizontal padding wrapper
            ui:HGroup{
                Spacing = 0,
                Weight = 1,
                ui:HGap(DIALOG_PADDING),

                ui:VGroup{
                    Weight = 1,
                    Spacing = 0,

                    -- ==========================================================
                    -- MAIN VIEW
                    -- ==========================================================
                    ui:VGroup{
                        ID = "MainView",
                        Weight = 1,
                        Spacing = 0,

                        ui:VGap(28),

                        ui:Label{
                            ID = "MainIcon",
                            Text = logoIcon(),
                            MinimumSize = ICON_SIZE,
                            MaximumSize = ICON_SIZE,
                            Weight = 0,
                            StyleSheet = ICON_STYLE,
                        },

                        ui:VGap(24),

                        ui:Label{
                            ID = "SuiteNameLabel",
                            Text = INSTALLER_TITLE,
                            Alignment = { AlignHCenter = true },
                            Font = ui:Font{ PixelSize = 20 },
                            Weight = 0,
                            StyleSheet = "font-weight: 600; color: " .. COLORS.primary .. ";",
                        },

                        ui:VGap(10),

                        -- Version pill badge
                        ui:HGroup{
                            Weight = 0,
                            ui:HGap(0, 1),
                            ui:Label{
                                ID = "VersionBadge",
                                Text = "v" .. INSTALLER_VERSION,
                                Weight = 0,
                                StyleSheet = VERSION_BADGE_STYLE,
                            },
                            ui:HGap(0, 1),
                        },

                        ui:VGap(0, 1),

                        ui:HGroup{
                            Weight = 0,
                            Spacing = 0,
                            ui:Button{
                                ID = "InstallButton",
                                Text = "Install",
                                Weight = 1,
                                MinimumSize = {0, 44},
                                StyleSheet = PRIMARY_BUTTON_STYLE,
                            },
                        },

                        ui:VGap(10),

                        ui:HGroup{
                            Weight = 0,
                            Spacing = 0,
                            ui:Button{
                                ID = "CustomButton",
                                Text = "Custom Installation",
                                Weight = 1,
                                MinimumSize = {0, 44},
                                StyleSheet = SECONDARY_BUTTON_STYLE,
                            },
                        },

                        ui:VGap(10),

                        ui:HGroup{
                            Weight = 0,
                            Spacing = 0,
                            ui:Button{
                                ID = "CancelButton",
                                Text = "Cancel",
                                Weight = 1,
                                MinimumSize = {0, 44},
                                StyleSheet = SECONDARY_BUTTON_STYLE,
                            },
                        },

                        ui:VGap(28),
                    },

                    -- ==========================================================
                    -- FAILURE VIEW (scripts directory could not be detected)
                    -- ==========================================================
                    ui:VGroup{
                        ID = "FailureView",
                        Hidden = true,
                        Weight = 1,
                        Spacing = 0,

                        ui:VGap(28),

                        ui:Label{
                            ID = "FailureIcon",
                            Text = failureIcon(),
                            MinimumSize = ICON_SIZE,
                            MaximumSize = ICON_SIZE,
                            Weight = 0,
                            StyleSheet = ICON_STYLE,
                        },

                        ui:VGap(24),

                        ui:Label{
                            Text = "Installation Failed",
                            Alignment = { AlignHCenter = true },
                            Font = ui:Font{ PixelSize = 20 },
                            Weight = 0,
                            StyleSheet = "font-weight: 600; color: " .. COLORS.primary .. ";",
                        },

                        ui:VGap(12),

                        ui:Label{
                            ID = "FailureMessage",
                            Text = "Could not detect the Fusion Scripts folder.\nCopy the scripts into Fusion/Scripts/Utility manually.",
                            Alignment = { AlignHCenter = true },
                            Font = ui:Font{ PixelSize = 12 },
                            Weight = 0,
                            WordWrap = true,
                            StyleSheet = "color: " .. COLORS.secondary .. ";",
                        },

                        ui:VGap(0, 1),

                        ui:HGroup{
                            Weight = 0,
                            Spacing = 0,
                            ui:Button{
                                ID = "FailCloseButton",
                                Text = "Close",
                                Weight = 1,
                                MinimumSize = {0, 44},
                                StyleSheet = SECONDARY_BUTTON_STYLE,
                            },
                        },

                        ui:VGap(28),
                    },
                },

                ui:HGap(DIALOG_PADDING),
            },
        })

        local itm = win:GetItems()

        function win.On.ESSuiteInstallerWin.Close(ev)
            disp:ExitLoop()
        end

        function win.On.CancelButton.Clicked(ev)
            disp:ExitLoop()
        end

        function win.On.FailCloseButton.Clicked(ev)
            disp:ExitLoop()
        end

        function win.On.InstallButton.Clicked(ev)
            if not installPath then
                itm.MainView.Hidden = true
                itm.FailureView.Hidden = false
                win:RecalcLayout()
                return
            end
            action = "install"
            disp:ExitLoop()
        end

        function win.On.CustomButton.Clicked(ev)
            action = "custom"
            disp:ExitLoop()
        end

        -- Ctrl+W / Ctrl+F4 hotkey to close window
        app:AddConfig(winID, {
            Target {
                ID = winID,
            },
            Hotkeys {
                Target = winID,
                Defaults = true,
                CONTROL_W = "Execute{ cmd = [[ app.UIManager:QueueEvent(obj, 'Close', {}) ]] }",
                CONTROL_F4 = "Execute{ cmd = [[ app.UIManager:QueueEvent(obj, 'Close', {}) ]] }",
            },
        })

        applyDialogPlatformAttributes(win)
        win:Resize({DIALOG_WIDTH, DIALOG_HEIGHT})
        win:RecalcLayout()
        win:Show()
        disp:RunLoop()
        win:Hide()
        app:RemoveConfig(winID)

        return action
    end

    -- ========================================================================
    -- SELECTION / RESULTS WINDOW (larger; hosts results from either path)
    -- ========================================================================

    -- Opens in the checkbox select view, or directly in the results view when
    -- resultLines is given (main-window Install path). Returns "back" when
    -- the user wants the main window again, nil otherwise.
    local function showSelectWindow(resultLines, resultsOk)
        local winID = "ESSuiteSelectWin"
        local DIALOG_PADDING = 28
        local DIALOG_WIDTH = 380
        local DIALOG_HEIGHT = math.max(420, 220 + 30 * #SCRIPTS)
        local action = nil

        -- Select view: checkbox rows only, then Install Selected / Back
        local selectChildren = {
            ID = "SelectView",
            Weight = 1,
            Spacing = 0,

            ui:VGap(28),
        }

        for i, entry in ipairs(SCRIPTS) do
            selectChildren[#selectChildren + 1] = ui:HGroup{
                Weight = 0,
                Spacing = 8,
                ui:CheckBox{
                    ID = "ScriptCheck" .. i,
                    Text = entry.name,
                    Checked = statuses[i].checked,
                    Font = ui:Font{ PixelSize = 12 },
                    Weight = 1,
                },
                ui:Label{
                    ID = "ScriptStatus" .. i,
                    Text = statuses[i].text,
                    Font = ui:Font{ PixelSize = 11 },
                    Weight = 0,
                    StyleSheet = "color: " .. COLORS.muted .. ";",
                },
            }
            selectChildren[#selectChildren + 1] = ui:VGap(6)
        end

        selectChildren[#selectChildren + 1] = ui:VGap(0, 1)
        selectChildren[#selectChildren + 1] = ui:HGroup{
            Weight = 0,
            Spacing = 0,
            ui:Button{
                ID = "InstallSelectedButton",
                Text = "Install Selected",
                Weight = 1,
                MinimumSize = {0, 44},
                StyleSheet = PRIMARY_BUTTON_STYLE,
            },
        }
        selectChildren[#selectChildren + 1] = ui:VGap(10)
        selectChildren[#selectChildren + 1] = ui:HGroup{
            Weight = 0,
            Spacing = 0,
            ui:Button{
                ID = "BackButton",
                Text = "Back",
                Weight = 1,
                MinimumSize = {0, 44},
                StyleSheet = SECONDARY_BUTTON_STYLE,
            },
        }
        selectChildren[#selectChildren + 1] = ui:VGap(28)

        local selectView = ui:VGroup(selectChildren)

        -- Results view: per-script outcome after install
        local resultsChildren = {
            ID = "ResultsView",
            Hidden = true,
            Weight = 1,
            Spacing = 0,

            ui:VGap(28),

            ui:Label{
                ID = "ResultsTitle",
                Text = "Installation Complete",
                Alignment = { AlignHCenter = true },
                Font = ui:Font{ PixelSize = 20 },
                Weight = 0,
                StyleSheet = "font-weight: 600; color: " .. COLORS.primary .. ";",
            },

            ui:VGap(12),

            ui:Label{
                Text = "Find the scripts in Workspace → Scripts → EditorScripts.",
                Alignment = { AlignHCenter = true },
                Font = ui:Font{ PixelSize = 12 },
                Weight = 0,
                WordWrap = true,
                StyleSheet = "color: " .. COLORS.secondary .. ";",
            },

            ui:VGap(28),
        }

        for i, entry in ipairs(SCRIPTS) do
            resultsChildren[#resultsChildren + 1] = ui:HGroup{
                Weight = 0,
                Spacing = 8,
                ui:Label{
                    Text = entry.name,
                    Font = ui:Font{ PixelSize = 12 },
                    Weight = 1,
                    StyleSheet = "color: " .. COLORS.primary .. ";",
                },
                ui:Label{
                    ID = "ResultStatus" .. i,
                    Text = "",
                    Font = ui:Font{ PixelSize = 11 },
                    Weight = 0,
                    StyleSheet = "color: " .. COLORS.muted .. ";",
                },
            }
            resultsChildren[#resultsChildren + 1] = ui:VGap(6)
        end

        -- Stretch gap: at the fixed window height the leftover here lands at
        -- ~DIALOG_PADDING above the buttons. Minimum must stay 0 — a larger
        -- minimum pushes the view's size hint past the window height and the
        -- window grows when switching from the select view.
        resultsChildren[#resultsChildren + 1] = ui:VGap(0, 1)
        resultsChildren[#resultsChildren + 1] = ui:HGroup{
            Weight = 0,
            Spacing = 0,
            ui:Button{
                ID = "CloseButton",
                Text = "Close",
                Weight = 1,
                MinimumSize = {0, 44},
                StyleSheet = PRIMARY_BUTTON_STYLE,
            },
        }
        resultsChildren[#resultsChildren + 1] = ui:VGap(10)
        resultsChildren[#resultsChildren + 1] = ui:HGroup{
            Weight = 0,
            Spacing = 0,
            ui:Button{
                ID = "OpenFolderButton",
                Text = "Open Install Folder",
                Weight = 1,
                MinimumSize = {0, 44},
                StyleSheet = SECONDARY_BUTTON_STYLE,
            },
        }
        resultsChildren[#resultsChildren + 1] = ui:VGap(28)

        local resultsView = ui:VGroup(resultsChildren)

        local win = disp:AddWindow({
            ID = winID,
            TargetID = winID,
            WindowTitle = "EditorScripts Installer",
            StyleSheet = "* { background-color: " .. COLORS.bg .. "; color: " .. COLORS.primary .. "; }",
            WindowFlags = dialogWindowFlags(),
            Events = {
                Close = true,
            },
        }, ui:VGroup{
            ID = "DialogRoot",
            MinimumSize = {DIALOG_WIDTH, DIALOG_HEIGHT},
            MaximumSize = {DIALOG_WIDTH, DIALOG_HEIGHT},
            Spacing = 0,

            -- Horizontal padding wrapper
            ui:HGroup{
                Spacing = 0,
                Weight = 1,
                ui:HGap(DIALOG_PADDING),

                ui:VGroup{
                    Weight = 1,
                    Spacing = 0,
                    selectView,
                    resultsView,
                },

                ui:HGap(DIALOG_PADDING),
            },
        })

        local itm = win:GetItems()

        local function showResults(lines, allOk)
            for i = 1, #SCRIPTS do
                itm["ResultStatus" .. i].Text = lines[i]
            end
            itm.ResultsTitle.Text = allOk and "Installation Complete" or "Finished with Errors"
            itm.SelectView.Hidden = true
            itm.ResultsView.Hidden = false
            win:Resize({DIALOG_WIDTH, DIALOG_HEIGHT})
            win:RecalcLayout()
        end

        function win.On.ESSuiteSelectWin.Close(ev)
            disp:ExitLoop()
        end

        function win.On.CloseButton.Clicked(ev)
            disp:ExitLoop()
        end

        function win.On.OpenFolderButton.Clicked(ev)
            bmd.openfileexternal("Open", installPath)
            disp:ExitLoop()
        end

        function win.On.BackButton.Clicked(ev)
            action = "back"
            disp:ExitLoop()
        end

        function win.On.InstallSelectedButton.Clicked(ev)
            local selected = {}
            local any = false
            for i = 1, #SCRIPTS do
                selected[i] = itm["ScriptCheck" .. i].Checked
                any = any or selected[i]
            end
            if not any then
                return
            end
            if not installPath then
                local lines = {}
                for i = 1, #SCRIPTS do
                    lines[i] = selected[i] and "Install failed" or "Not selected"
                end
                consolePrint("[EditorScripts Installer] ERROR: Could not detect the scripts directory.")
                showResults(lines, false)
                return
            end
            showResults(runInstall(selected))
        end

        -- Show directly in the results view (main-window Install path)
        if resultLines then
            showResults(resultLines, resultsOk)
        end

        -- Ctrl+W / Ctrl+F4 hotkey to close window
        app:AddConfig(winID, {
            Target {
                ID = winID,
            },
            Hotkeys {
                Target = winID,
                Defaults = true,
                CONTROL_W = "Execute{ cmd = [[ app.UIManager:QueueEvent(obj, 'Close', {}) ]] }",
                CONTROL_F4 = "Execute{ cmd = [[ app.UIManager:QueueEvent(obj, 'Close', {}) ]] }",
            },
        })

        applyDialogPlatformAttributes(win)
        win:Resize({DIALOG_WIDTH, DIALOG_HEIGHT})
        win:RecalcLayout()
        win:Show()
        disp:RunLoop()
        win:Hide()
        app:RemoveConfig(winID)

        return action
    end

    -- ========================================================================
    -- WINDOW FLOW
    -- ========================================================================

    while true do
        local mainAction = showMainWindow()

        if mainAction == "install" then
            local selected = {}
            for i = 1, #SCRIPTS do
                selected[i] = true
            end
            showSelectWindow(runInstall(selected))
            break
        elseif mainAction == "custom" then
            if showSelectWindow(nil) ~= "back" then
                break
            end
            -- Back pressed: loop around and reshow the main window
        else
            break
        end
    end

    collectgarbage()
end
-- ============================================================================
-- MAIN
-- ============================================================================

local IS_SUITE = #SCRIPTS > 1

consolePrint("")
consolePrint("============================================================")
consolePrint("[EditorScripts Installer] " .. INSTALLER_TITLE .. " v" .. INSTALLER_VERSION)
consolePrint("============================================================")

if IS_SUITE then
    for _, entry in ipairs(SCRIPTS) do
        consolePrint("[EditorScripts Installer]   Bundled: " .. entry.name .. " v" .. entry.version)
    end
    showSuiteDialog()
else
    showInstallerDialog()
end
